/** Блок для промпта или null, если карточки для пары «экзамен + предмет» нет. */
export function examFormat(goal: StudyGoal, subject: string): string | null {
  const format = FORMATS[goal]?.[subject]
  if (!format) return null
  return [
    'Формат экзамена — типы заданий из демоверсии. Образцы показывают формулировку, сложность и вид ответа; не переписывай их, составь свои задания на тему урока:',
    ...format.types.map((t) => `— ${t}`),
    `Ответ на экзамене: ${format.answer}`,
  ].join('\n')
}
